var formatter = new Intl.Collator('en');
function invoke(){return String(Math.sign(formatter.compare('a','b')))}
var expected="-1";
if(invoke()!==expected)throw new Error("initial output");
var sum=0;var start=__now();
for(var i=0;i<3000000;i++)sum+=invoke().length;
var elapsed=__now()-start;
if(invoke()!==expected)throw new Error("final output");
print(JSON.stringify({name:"collator",calls:3000000,us:elapsed*1000/3000000,checksum:sum}));
